package org.example.backend.service;
import org.example.backend.service.impl.VoskSpeechRecognitionServiceImpl;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import org.vosk.Model;
import org.vosk.Recognizer;
import tools.jackson.databind.ObjectMapper;
import java.nio.file.*;
import java.util.stream.Stream;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class SpeechRecognitionBehaviorTest {
    @Test void failedNativeModelAndCopyFallbackDisableRecognition(){try(var files=mockStatic(Files.class);var models=mockConstruction(Model.class,(model,context)->{throw new IllegalStateException("native load failed");})){files.when(()->Files.isDirectory(any(Path.class))).thenReturn(true);files.when(()->Files.walk(any(Path.class))).thenThrow(new java.io.IOException("copy failed"));var service=new VoskSpeechRecognitionServiceImpl(new ObjectMapper(),new MockEnvironment().withProperty("speech.vosk.model-path","C:/test-model"));assertFalse(service.isAvailable());assertThrows(IllegalStateException.class,service::createRecognizer);}}
    @Test void failedRecognizerConstructionHasActionableError(){try(var files=mockStatic(Files.class);var models=mockConstruction(Model.class);var recognizers=mockConstruction(Recognizer.class,(recognizer,context)->{throw new IllegalStateException("native recognizer failed");})){files.when(()->Files.isDirectory(any(Path.class))).thenReturn(true);var service=new VoskSpeechRecognitionServiceImpl(new ObjectMapper(),new MockEnvironment().withProperty("speech.vosk.model-path","C:/test-model"));assertTrue(assertThrows(IllegalStateException.class,service::createRecognizer).getMessage().contains("无法创建"));}}
    @Test void absentModelDisablesRecognitionWithoutCrashingApplication(){MockEnvironment env=new MockEnvironment().withProperty("speech.vosk.model-path","Z:/missing-test-model");var service=new VoskSpeechRecognitionServiceImpl(new ObjectMapper(),env);assertFalse(service.isAvailable());assertThrows(IllegalStateException.class,service::createRecognizer);assertEquals("",service.getResultText(null));assertEquals("",service.getPartialText(null));assertEquals("",service.getFinalText(null));}
    @Test void recognizerResultParsingTrimsTextAndRecoversMalformedJson(){var service=new VoskSpeechRecognitionServiceImpl(new ObjectMapper(),new MockEnvironment().withProperty("speech.vosk.model-path","Z:/missing-test-model"));Recognizer recognizer=mock(Recognizer.class);when(recognizer.getResult()).thenReturn("{\"text\":\" 实验室 \"}");when(recognizer.getPartialResult()).thenReturn("{\"partial\":\" 临时 \"}");when(recognizer.getFinalResult()).thenReturn("{\"text\":\" 完成 \"}");assertEquals("实验室",service.getResultText(recognizer));assertEquals("临时",service.getPartialText(recognizer));assertEquals("完成",service.getFinalText(recognizer));when(recognizer.getResult()).thenReturn("malformed");assertEquals("",service.getResultText(recognizer));when(recognizer.getFinalResult()).thenReturn("{}");assertEquals("",service.getFinalText(recognizer));}
    @Test void asciiModelLoadsWithNativeConstructionMockedAndUsesPcm16kRecognizer(){Model.class.getName();try(var files=mockStatic(Files.class);var models=mockConstruction(Model.class);var recognizers=mockConstruction(Recognizer.class)){files.when(()->Files.isDirectory(any(Path.class))).thenReturn(true);var service=new VoskSpeechRecognitionServiceImpl(new ObjectMapper(),new MockEnvironment().withProperty("speech.vosk.model-path","C:/test-model"));assertTrue(service.isAvailable());assertNotNull(service.createRecognizer());assertEquals(1,models.constructed().size());assertEquals(1,recognizers.constructed().size());}}
    @Test void nonAsciiModelPathsUseCopyWithoutTouchingRealFilesystem(){Path source=Path.of("C:/模型/test-model").toAbsolutePath().normalize();Path weight=source.resolve("am").resolve("final.mdl");try(var files=mockStatic(Files.class);var models=mockConstruction(Model.class)){files.when(()->Files.isDirectory(any(Path.class))).thenAnswer(call->!call.getArgument(0).equals(weight));files.when(()->Files.walk(source)).thenAnswer(call->Stream.of(source,source.resolve("am"),weight));var service=new VoskSpeechRecognitionServiceImpl(new ObjectMapper(),new MockEnvironment().withProperty("speech.vosk.model-path",source.toString()));assertTrue(service.isAvailable());files.verify(()->Files.copy(eq(weight),any(Path.class),eq(StandardCopyOption.REPLACE_EXISTING)));assertEquals(1,models.constructed().size());}}
}
